for fname, reps in ai_exact_replacements.items():
    fpath = os.path.join(ai_dir, fname)
    if os.path.exists(fpath):
        with open(fpath, "r", encoding="utf-8") as f:
            content = f.read()
        orig = content
        for target, repl in reps:
            content = content.replace(target, repl)
        if content != orig:
            with open(fpath, "w", encoding="utf-8") as f:
                f.write(content)
            print(f"Cleaned AI {fname}")

print("AI Essentials text cleaning complete!")
